private <K,V extends SessionEntity>void runOnRemoteCache(RemoteCache<K,SessionEntityWrapper<V>> remoteCache,long maxIdleMs,K key,SessionUpdateTask<V> task,SessionEntityWrapper<V> sessionWrapper){
  final V session=sessionWrapper.getEntity();
  SessionUpdateTask.CacheOperation operation=task.getOperation(session);
switch (operation) {
case REMOVE:    remoteCache.remove(key);
  break;
case ADD:remoteCache.put(key,sessionWrapper.forTransport(),task.getLifespanMs(),TimeUnit.MILLISECONDS,maxIdleMs,TimeUnit.MILLISECONDS);
break;
case ADD_IF_ABSENT:final int currentTime=Time.currentTime();
SessionEntityWrapper<V> existing=remoteCache.withFlags(Flag.FORCE_RETURN_VALUE).putIfAbsent(key,sessionWrapper.forTransport(),-1,TimeUnit.MILLISECONDS,maxIdleMs,TimeUnit.MILLISECONDS);
if (existing != null) {
logger.debugf("Existing entity in remote cache for key: %s . Will update it",key);
replace(remoteCache,task.getLifespanMs(),maxIdleMs,key,task);
}
 else {
try {
  sessionWrapper.putLocalMetadataNoteInt(UserSessionEntity.LAST_SESSION_REFRESH_REMOTE,currentTime);
} catch (UnsupportedOperationException | IllegalArgumentException | NullPointerException e) {
  logger.warnf("Failed to update local metadata note for key: %s due to: %s", key, e.getMessage());
}
}
break;
case REPLACE:replace(remoteCache,task.getLifespanMs(),maxIdleMs,key,task);
break;
default:throw new IllegalStateException("Unsupported state " + operation);
}
}
